/**
 * Unpack: an object in, each key out of the output named for it.
 *
 * Max's `unpack`, by name rather than position: name the outputs after the
 * keys you want.  An array is unpacked by index (0, 1, 2).  Outputs fire last
 * first, for the same reason Trigger does — so nothing downstream sees half
 * of an object.  A key with no output is left alone rather than lost quietly:
 * it goes out `rest` if there is one.
 */
const source = Array.isArray(value)
    ? value.reduce((o, v, i) => { o[String(i)] = v; return o; }, {})
    : (value && typeof value === "object" ? value : {value: value});
const names = ((properties.outputs || []).map((o) => o.name)).reverse();
const rest = {};
Object.keys(source).forEach((key) => { if (names.indexOf(key) === -1) { rest[key] = source[key]; } });
for (const name of names) {
    if (name === "rest") { continue; }
    if (source[name] !== undefined) { edges[name] = source[name]; }
}
if (names.indexOf("rest") !== -1 && Object.keys(rest).length) { edges.rest = rest; }
